<script lang="ts">
import {tick} from 'svelte';import Icon from './Icon.svelte';import {dateISO,dateText,maskDate,monthDays,moveMonth,todayISO} from './calendar';
let {label,value=$bindable(''),language,t}:{label:string;value?:string;language:string;t:(key:string)=>string}=$props();
let root:HTMLDivElement;let input:HTMLInputElement;let popup=$state<HTMLDivElement>();let open=$state(false);let month=$state(todayISO().slice(0,7)+'-01');let position=$state({left:0,top:0});
let cells=$derived(monthDays(month));let monthLabel=$derived(new Intl.DateTimeFormat(language,{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(month+'T12:00:00Z')));
const weekdays=(lang:string)=>Array.from({length:7},(_,index)=>new Intl.DateTimeFormat(lang,{weekday:'short',timeZone:'UTC'}).format(new Date(Date.UTC(2026,0,5+index))));
function close(){open=false;input?.focus();}
async function show(){const rect=root.getBoundingClientRect();month=(dateISO(value)??todayISO()).slice(0,7)+'-01';position={left:Math.max(8,Math.min(rect.left,window.innerWidth-296)),top:rect.bottom+8+315<window.innerHeight?rect.bottom+8:Math.max(8,rect.top-323)};open=true;await tick();popup?.showPopover?.();popup?.querySelector<HTMLButtonElement>('[aria-pressed="true"]')?.focus();}
function edit(event:Event){const field=event.currentTarget as HTMLInputElement;const raw=field.value;const before=raw.slice(0,field.selectionStart??raw.length).replace(/\D/g,'').length;value=maskDate(raw);field.value=value;let cursor=0;let count=0;while(cursor<value.length&&count<before){if(/\d/.test(value[cursor]))count++;cursor++;}while(value[cursor]==='.')cursor++;field.setSelectionRange(cursor,cursor);}
function key(event:KeyboardEvent){if(event.key==='ArrowDown'){event.preventDefault();void show();}if(event.key==='Backspace'&&input.selectionStart===input.selectionEnd&&input.selectionStart&&input.value[input.selectionStart-1]==='.'){event.preventDefault();const cursor=input.selectionStart;const raw=input.value.slice(0,cursor-2)+input.value.slice(cursor);value=maskDate(raw);input.value=value;input.setSelectionRange(Math.max(0,cursor-2),Math.max(0,cursor-2));}}
</script>
<svelte:window onpointerdown={event=>{if(open&&!root?.contains(event.target as Node))open=false;}} onkeydown={event=>{if(open&&event.key==='Escape'){event.preventDefault();event.stopPropagation();close();}}}/>
<div class="date-picker" bind:this={root}><label class="profile-field"><span class="date-label">{label}</span><input bind:this={input} aria-label={label} {value} placeholder={t('ДД.ММ.ГГГГ')} inputmode="numeric" maxlength="10" autocomplete="off" oninput={edit} onkeydown={key}/><button type="button" class="icon-button" aria-label={t('Открыть календарь')} onclick={()=>{if(open)close();else void show();}}><Icon name="calendar_days"/></button></label>
{#if open}<div class="date-popup popup" popover="manual" bind:this={popup} style:left={`${position.left}px`} style:top={`${position.top}px`}><div class="month-bar"><button type="button" class="icon-button" aria-label={t('Предыдущий месяц')} disabled={month<='0001-01-01'} onclick={()=>month=moveMonth(month,-1)}><Icon name="back"/></button><strong>{monthLabel}</strong><button type="button" class="icon-button next" aria-label={t('Следующий месяц')} disabled={month>='9998-12-01'} onclick={()=>month=moveMonth(month,1)}><Icon name="back"/></button></div><div class="calendar-grid">{#each weekdays(language) as day}<small>{day}</small>{/each}{#each cells as day}<button type="button" class:adjacent={day.slice(0,7)!==month.slice(0,7)} class:chosen={day===dateISO(value)} aria-pressed={day===dateISO(value)} disabled={day<'0001-01-01'||day>='9999-01-01'} aria-label={new Intl.DateTimeFormat(language,{dateStyle:'long',timeZone:'UTC'}).format(new Date(day+'T12:00:00Z'))} onclick={()=>{value=dateText(day);close();}}>{Number(day.slice(8))}</button>{/each}</div></div>{/if}</div>
<style>.date-picker{min-width:0}.date-picker .profile-field{display:flex;align-items:center;gap:8px;padding:4px 8px 4px 12px;min-height:44px}.date-label{color:var(--muted);flex:1}.date-picker input{width:105px;text-align:right;font-variant-numeric:tabular-nums;background:none;color:var(--text);border:0;outline:none;min-width:0;padding:4px 0}.date-picker .icon-button{width:28px;height:28px;min-height:28px;padding:4px}.date-popup{position:fixed;inset:auto;margin:0;width:280px;padding:10px;z-index:30;background:var(--surface);color:var(--text)}.month-bar{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:6px}.month-bar strong{text-transform:capitalize;font-size:13px}.next :global(svg){transform:rotate(180deg)}.calendar-grid{display:grid;grid-template-columns:repeat(7,1fr);gap:2px}.calendar-grid small{text-align:center;color:var(--muted);padding:5px 0}.calendar-grid button{min-height:30px;border:0;border-radius:5px;padding:4px;justify-content:center;background:transparent}.calendar-grid button.chosen{background:var(--accent);color:white}.calendar-grid .adjacent{color:var(--muted)}</style>
